 @Test public void selectedEpisodeCompletesExactlyWithoutDownloadingTheOtherFileAndSharingOffRemovesHandle()throws Exception{try(Fixture f=new Fixture(true)){f.enqueue();f.until(()->f.store.job(f.id()).optString("status").equals("complete"),60000);assertArrayEquals(f.first,Files.readAllBytes(f.store.file(f.id(),false).toPath()));assertFalse(f.data.localFile(f.id()).isEmpty());assertEquals(0,f.store.torrents.count());assertNull(PhoneTorrent.session().find(f.info.infoHash()));assertFalse(new File(f.store.directory,".torrents/"+f.info.infoHash().toHex()+"/"+f.info.files().filePath(f.other)).exists());assertFalse(new File(f.store.directory,".torrents/"+f.info.infoHash().toHex()).exists());f.store.remove(f.id());assertFalse(f.store.file(f.id(),false).exists());assertEquals("",f.data.localFile(f.id()));}}
 @Test public void sdDefaultStagesAndCompletesOnTheJobVolumeEvenAfterDefaultChanges()throws Exception{try(Fixture f=new Fixture(true)){File sd=new File(f.root,"sd/offline");f.store.defaultDirectory(sd);f.enqueue();f.store.defaultDirectory(f.store.directory);f.until(()->f.store.job(f.id()).optLong("bytes")>65536,20000);assertEquals(sd,f.store.file(f.id(),false).getParentFile());assertEquals(new File(sd,".torrents/"+f.info.infoHash().toHex()).getCanonicalFile(),new File(f.store.torrents.handle(f.id()).savePath()).getCanonicalFile());assertTrue(new File(sd,".torrents/"+f.info.infoHash().toHex()).isDirectory());assertFalse(new File(f.store.directory,".torrents/"+f.info.infoHash().toHex()).exists());f.store.pause(f.id());f.store.torrents.tick();f.store=new DownloadStore(f.context);NoirApp.downloads=f.store;f.store.enqueue(f.data.item(f.id()));f.until(()->f.store.job(f.id()).optString("status").equals("complete"),60000);File ready=f.store.file(f.id(),false);assertEquals(sd,ready.getParentFile());assertArrayEquals(f.first,Files.readAllBytes(ready.toPath()));assertEquals(android.net.Uri.fromFile(ready).toString(),f.data.localFile(f.id()));assertFalse(new File(sd,".torrents/"+f.info.infoHash().toHex()).exists());f.store.remove(f.id());assertFalse(ready.exists());}}
 @Test public void pauseResumeAndRestartRetainResumeDataAndRemoveDeletesPartialData()throws Exception{try(Fixture f=new Fixture(true)){f.enqueue();f.until(()->f.store.job(f.id()).optLong("bytes")>65536,20000);TorrentHandle handle=f.store.torrents.handle(f.id());assertEquals(Priority.IGNORE,handle.filePriority(f.other));assertEquals(0,handle.fileProgress()[f.other]);f.store.pause(f.id());f.store.torrents.tick();assertEquals("paused",f.store.job(f.id()).optString("status"));File resume=new File(f.context.getFilesDir(),"torrent-engine/"+f.info.infoHash().toHex()+".resume");assertTrue(resume.isFile());long partial=f.store.job(f.id()).optLong("bytes");f.store=new DownloadStore(f.context);NoirApp.downloads=f.store;assertEquals("paused",f.store.job(f.id()).optString("status"));f.store.enqueue(f.data.item(f.id()));f.until(()->f.store.job(f.id()).optLong("bytes")>partial,20000);f.store.remove(f.id());assertNull(f.store.job(f.id()));assertFalse(resume.exists());assertFalse(new File(f.store.directory,".torrents/"+f.info.infoHash().toHex()).exists());assertFalse(f.store.file(f.id(),false).exists());}}
 @Test public void meteredNetworkPausesAndUnmeteredNetworkResumesAndSharingStopsWithService()throws Exception{try(Fixture f=new Fixture(true)){JSONObject settings=new PhoneDownloadSettings(f.context).load();DataStore.put(settings,"torrentSharing","forever");new PhoneDownloadSettings(f.context).save(settings);PhoneTorrent.unmeteredOverride=c->false;f.enqueue();f.store.torrents.tick();assertEquals("Waiting for Wi-Fi",f.store.job(f.id()).optString("torrentMessage"));assertEquals(0,f.store.torrents.count());PhoneTorrent.unmeteredOverride=c->true;f.until(()->f.store.job(f.id()).optLong("bytes")>0,20000);PhoneTorrent.unmeteredOverride=c->false;f.store.torrents.tick();assertEquals("Waiting for Wi-Fi",f.store.job(f.id()).optString("torrentMessage"));PhoneTorrent.unmeteredOverride=c->true;f.until(()->f.store.job(f.id()).optString("status").equals("complete"),60000);assertEquals("Sharing back",f.store.job(f.id()).optString("torrentMessage"));f.store.torrents.stopAll();assertEquals(0,f.store.torrents.count());assertTrue(f.store.file(f.id(),false).exists());}}
 @Test public void sharingBackTakesNoDownloadSlotAndStopsWhenTorrentsAreTurnedOff()throws Exception{try(Fixture f=new Fixture(true)){JSONObject settings=new PhoneDownloadSettings(f.context).load();DataStore.put(settings,"torrentSharing","forever");new PhoneDownloadSettings(f.context).save(settings);f.enqueue();f.until(()->f.store.job(f.id()).optString("status").equals("complete"),60000);assertEquals(1,f.store.torrents.count());assertEquals("A finished torrent that is sharing back must not block queued downloads",0,f.store.torrents.downloading());DataStore.put(settings,"torrents",false);new PhoneDownloadSettings(f.context).save(settings);f.store.torrents.tick();assertEquals(0,f.store.torrents.count());assertFalse("Turning torrents off releases the foreground service",f.store.torrents.busy());assertEquals("complete",f.store.job(f.id()).optString("status"));assertTrue(f.store.file(f.id(),false).exists());}}
 @Test public void missingMetadataSwitchesToUntriedPlannerAlternativeAndCompletes()throws Exception{try(Fixture f=new Fixture(true)){JSONObject abandoned=DataStore.copy(f.choice);DataStore.put(abandoned,"hash","0123456789012345678901234567890123456789");abandoned.remove("peerPort");DataStore.put(abandoned,"alternatives",new JSONArray().put(DataStore.copy(abandoned)).put(f.choice));PhoneTorrent.metadataTimeoutMs=150;f.store.enqueuePhone(f.item,abandoned);f.until(()->f.store.job(f.id()).optInt("torrentSwitches")==1,10000);assertEquals("queued",f.store.job(f.id()).optString("status"));assertEquals(PhoneTorrent.SWITCHED,f.store.job(f.id()).optString("switchMessage"));assertFalse(new File(f.store.directory,".torrents/"+abandoned.optString("hash")).exists());f.until(()->f.store.job(f.id()).optString("status").equals("complete"),60000);assertArrayEquals(f.first,Files.readAllBytes(f.store.file(f.id(),false).toPath()));}}
 @Test public void noPeersFailsWithFriendlyMessageAndNeverLeaksTheSource()throws Exception{try(Fixture f=new Fixture(false)){PhoneTorrent.stallTimeoutMs=150;f.enqueue();f.until(()->f.store.job(f.id()).optString("status").equals("failed"),15000);assertEquals(PhoneTorrent.EMPTY,f.store.job(f.id()).optString("error"));assertFalse(new File(f.store.directory,".torrents/"+f.info.infoHash().toHex()).exists());}}
 @Test public void settingsDefaultsAndEncryptedRoundTrip()throws Exception{try(Fixture f=new Fixture(false)){PhoneDownloadSettings s=new PhoneDownloadSettings(f.context);s.save(new JSONObject());JSONObject defaults=s.load();assertFalse(defaults.optBoolean("torrents"));assertFalse(defaults.optBoolean("torrentMobile"));assertTrue(defaults.optBoolean("torrentAutoSwitch"));assertEquals("ratio",defaults.optString("torrentSharing"));assertEquals(512,defaults.optInt("torrentUploadKB"));DataStore.put(defaults,"torrents",true);DataStore.put(defaults,"torrentMobile",true);DataStore.put(defaults,"torrentSharing","forever");DataStore.put(defaults,"torrentUploadKB",123);DataStore.put(defaults,"torrentAutoSwitch",false);s.save(defaults);JSONObject saved=new PhoneDownloadSettings(f.context).load();assertTrue(saved.optBoolean("torrents"));assertTrue(saved.optBoolean("torrentMobile"));assertEquals("forever",saved.optString("torrentSharing"));assertEquals(123,saved.optInt("torrentUploadKB"));assertFalse(saved.optBoolean("torrentAutoSwitch"));String disk=new String(Files.readAllBytes(new File(f.context.getFilesDir(),"phone-download-settings.enc").toPath()),StandardCharsets.UTF_8);assertFalse(disk.contains("torrentSharing"));}}
 @Test public void seedersHealthRankingAndPlaybackExclusion()throws Exception{
  assertEquals(12,PhoneDownloadProvider.seeders(json("{title:'[NOIR_SEEDERS:12] 👤 99',seeders:2}")));assertEquals(20,PhoneDownloadProvider.seeders(json("{seeders:20}")));assertEquals(4,PhoneDownloadProvider.seeders(json("{streamData:{torrent:{seeders:4}}}")));assertEquals(1234,PhoneDownloadProvider.seeders(json("{description:'👥 1,234'}")));assertEquals(1200,PhoneDownloadProvider.seeders(json("{title:'👤 1.2k'}")));assertEquals(-1,PhoneDownloadProvider.seeders(json("{}")));assertEquals("Dead",PhoneDownloadProvider.health(0));assertEquals("Low",PhoneDownloadProvider.health(9));assertEquals("Good",PhoneDownloadProvider.health(10));assertEquals("Unknown",PhoneDownloadProvider.health(-1));
  JSONObject settings=json("{torrents:true,preferredResolution:'1080p'}"),item=json("{movie:false,season:1,episode:1}");JSONArray streams=new JSONArray();for(int n=0;n<4;n++)streams.put(json("{infoHash:'"+String.format(Locale.ROOT,"%040d",n+1)+"',fileIdx:0,title:'"+(n==0?"[NOIR_SEEDERS:0]":n==1?"[NOIR_SEEDERS:2]":n==2?"[NOIR_SEEDERS:12]":"Unknown")+"',sources:['tracker:https://tracker.invalid/announce'],behaviorHints:{filename:'Show.S01E01.mkv',videoSize:1000}}"));JSONObject response=new JSONObject();DataStore.put(response,"streams",streams);List<JSONObject> choices=PhoneDownloadProvider.parse(response,item,settings);assertEquals(3,choices.size());List<JSONObject> ranked=PhoneDownloadProvider.ranked(choices,settings,"");assertEquals("Good",ranked.get(0).optString("health"));assertEquals("Unknown",ranked.get(1).optString("health"));assertEquals("Low",ranked.get(2).optString("health"));assertEquals("https://tracker.invalid/announce",ranked.get(0).optJSONArray("trackers").optString(0));assertEquals(3,ranked.get(0).optJSONArray("alternatives").length());assertTrue(PhoneStream.rank(choices,"1080p",false).isEmpty());assertTrue(TvStreamPick.rank(choices,new TvStreamPick.Profile(),0).isEmpty());DataStore.put(settings,"torBoxKey","fixture");for(JSONObject c:PhoneDownloadProvider.parse(response,item,settings))assertFalse(c.optString("service").equals("torrent"));DataStore.put(settings,"torBoxKey","");DataStore.put(settings,"torrents",false);assertTrue(PhoneDownloadProvider.parse(response,item,settings).isEmpty());
 }
